const t=k=>dict[lang][k]||({closedDate:lang==='ar'?'تاريخ الإغلاق':'Closed Date',trailTitle:lang==='ar'?'سجل التغييرات':'Audit Trail'})[k]||k, roleName=r=>lang==='ar'?({'Administrator':'مسؤول النظام','HSE / Safety Officer':'مسؤول الصحة والسلامة','Permit Controller':'مراقب التصاريح','Certificate Officer':'مسؤول الشهادات','Auditor':'مدقق','Personnel Officer':'مسؤول الموظفين','Viewer / Read Only':'مشاهد / قراءة فقط'}[r]||r):r, trStatus=s=>({Draft:t('draft'),Submitted:t('submitted'),'Under Review':t('review'),Approved:t('approved'),Rejected:t('rejected'),Closed:t('closed'),Archived:t('archived'),Valid:t('valid'),'Expiring Soon':t('expSoon'),Expired:t('expiredStatus'),Suspended:t('suspended'),'Pending Verification':t('pendingVerify')})[s]||s||'';
