function openDB(){return new Promise((resolve,reject)=>{const r=indexedDB.open(DB,VERSION);r.onupgradeneeded=()=>{const d=r.result;['ptw','audits','certificates','personnel','companies','findings','attachments','trail','users','formRecords'].forEach(s=>{if(!d.objectStoreNames.contains(s))d.createObjectStore(s,{keyPath:'id'})})};r.onblocked=()=>toast(lang==='ar'?'أغلق علامات تبويب النظام القديمة لإكمال ترقية قاعدة البيانات.':'Close older workspace tabs to finish the local database upgrade.');r.onsuccess=()=>{r.result.onversionchange=()=>r.result.close();resolve(r.result)};r.onerror=()=>reject(r.error)})}
function all(store){return new Promise((res,rej)=>{const q=db.transaction(store).objectStore(store).getAll();q.onsuccess=()=>res(q.result||[]);q.onerror=()=>rej(q.error)})}function put(store,v){return new Promise((res,rej)=>{const q=db.transaction(store,'readwrite').objectStore(store).put(v);q.onsuccess=()=>res(v);q.onerror=()=>rej(q.error)})}function del(store,id){return new Promise((res,rej)=>{const q=db.transaction(store,'readwrite').objectStore(store).delete(id);q.onsuccess=()=>res();q.onerror=()=>rej(q.error)})}
function allowed(action,entity){if(role==='Administrator')return true;if(role==='Viewer / Read Only')return false;const owner=specs[entity]?.owner;if(action==='delete')return role==='Administrator';if(action==='approve')return ['Administrator','HSE / Safety Officer','Permit Controller'].includes(role);if(entity==='ptw')return ['Permit Controller','HSE / Safety Officer'].includes(role);if(entity==='audits'||entity==='findings')return ['Auditor','HSE / Safety Officer'].includes(role);if(entity==='certificates')return role==='Certificate Officer';if(entity==='personnel')return role==='Personnel Officer';if(entity==='companies')return role==='Administrator';return role===owner}
function canTransition(from,to){if(from===to)return true;if(to==='Archived')return window.HSEPermissions.canArchive();if(to==='Submitted')return from==='Draft'&&role!=='Viewer / Read Only';if(to==='Under Review')return from==='Submitted'&&['Administrator','HSE / Safety Officer','Permit Controller','Auditor'].includes(role);if(to==='Approved'||to==='Rejected')return from==='Under Review'&&window.HSEPermissions.canApprove();if(to==='Closed')return from==='Approved'&&['Administrator','HSE / Safety Officer','Permit Controller'].includes(role);return to==='Draft'&&from==='Draft'}
window.HSEPermissions={canCreate:e=>allowed('create',e),canEdit:e=>allowed('edit',e),canDelete:e=>allowed('delete',e),canApprove:e=>allowed('approve',e),canArchive:e=>role==='Administrator'||role==='Permit Controller'};
function toast(s){const el=document.createElement('div');el.className='toast';el.textContent=s;document.body.append(el);setTimeout(()=>el.remove(),2800)}function log(action,entity,record,oldValue,newValue){return put('trail',{id:uid(),user:role||'Unknown',action,entity,record,oldValue:oldValue||'',newValue:newValue||'',time:new Date().toISOString()})}
function shell(path){const app=document.querySelector('#app');document.documentElement.lang=lang;document.documentElement.dir=lang==='ar'?'rtl':'ltr';document.body.classList.toggle('dark',dark);const pageKey=(menus.find(m=>m[2]===path)||[])[1]||'dashboard';app.innerHTML=`<div class="shell"><button class="nav-backdrop" id="nav-close" aria-label="${lang==='ar'?'إغلاق القائمة':'Close navigation'}"></button><aside class="side" id="sidebar"><div class="brand"><span class="brand-icon" aria-hidden="true">⛑</span><span><b>PTW Pro</b><small>${t('brand')}</small></span></div><nav class="navlist" aria-label="${lang==='ar'?'التنقل الرئيسي':'Primary navigation'}">${menus.map(([g,k,url,ico],i)=>`${i===0||menus[i-1][0]!==g?`<div class="navgroup">${t(g)}</div>`:''}<a class="nav ${path===url?'active':''}" href="${url}"><span class="ico" aria-hidden="true">${ico}</span><span>${t(k)}</span><span class="nav-arrow" aria-hidden="true">›</span></a>`).join('')}</nav><div class="sidefoot"><span class="side-status"></span>${lang==='ar'?'مساحة عمل محلية':'Local workspace'}<small>PTW • HSE</small></div></aside><main class="main"><header class="top"><div class="top-start"><button class="menu-toggle" id="nav-toggle" aria-label="${lang==='ar'?'فتح القائمة':'Open navigation'}">☰</button><div class="top-heading"><span class="top-kicker">${t('subtitle')}</span><strong>${t(pageKey)}</strong></div></div><div class="tools"><label class="role-tool"><span aria-hidden="true">◉</span><select id="role-select" aria-label="${t('role')}"><option value="">${t('role')}</option>${roles.map(r=>`<option value="${esc(r)}" ${r===role?'selected':''}>${roleName(r)}</option>`).join('')}</select></label><button class="btn small tool-button" id="lang" aria-label="${t('language')}">${lang==='en'?'عربي':'English'}</button><button class="btn small tool-button theme-button" id="theme" aria-label="${t('theme')}">${dark?'☀':'◐'}</button><button class="btn small notification-button" aria-label="${lang==='ar'?'الإشعارات':'Notifications'}">🔔<i></i></button><span class="profile-chip"><span class="avatar" aria-hidden="true">${role?roleName(role).slice(0,1):'•'}</span><span>${role?roleName(role):t('loginTitle')}</span></span>${role?`<button class="btn small logout-button" id="logout-shell" type="button">${t('logout')}</button>`:''}</div></header><section class="content" id="view"></section><div class="footer">${t('roleNote')}</div></main></div>`;
document.querySelector('#lang').onclick=()=>{lang=lang==='en'?'ar':'en';localStorage.setItem(LANGKEY,lang);render()};document.querySelector('#theme').onclick=()=>{dark=!dark;localStorage.setItem(THEMEKEY,dark?'dark':'light');render()};document.querySelector('#role-select').onchange=e=>{role=e.target.value;sessionStorage.setItem(ROLEKEY,role);render()};document.querySelector('#logout-shell')?.addEventListener('click',()=>{sessionStorage.removeItem(ROLEKEY);role='';render()});const sidebar=document.querySelector('#sidebar');const closeNav=()=>{sidebar.classList.remove('open');document.body.classList.remove('nav-open')};document.querySelector('#nav-toggle').onclick=()=>{sidebar.classList.toggle('open');document.body.classList.toggle('nav-open',sidebar.classList.contains('open'))};document.querySelector('#nav-close').onclick=closeNav;sidebar.querySelectorAll('a').forEach(a=>a.addEventListener('click',closeNav));}function pageHead(title,sub,button=''){return `<div class="welcome"><div><h1>${t(title)}</h1><div class="sub">${sub||''}</div></div>${button}</div>`}function metric(label,value,hint='',icon='◫',tone='green'){return `<article class="card metric metric-${tone}"><div class="metric-top"><span class="metric-icon" aria-hidden="true">${icon}</span><span class="metric-live">${t('liveData')}</span></div><div class="label">${label}</div><div class="value">${value}</div><div class="hint">${hint}</div></article>`}Object.assign(dict.en,{pendingApproval:'Pending approval',totalPersonnel:'Total personnel',recentActivity:'Recent activity',recentPermits:'Recent permits',permitKinds:'Permits by type',liveData:'Live data',viewAll:'View all',formCount:'Reference Forms',submittedForms:'Submitted Forms',archivedForms:'Archived Forms',duplicateForm:'This form number is already in use.'});Object.assign(dict.ar,{pendingApproval:'بانتظار الاعتماد',totalPersonnel:'إجمالي الموظفين',recentActivity:'آخر النشاطات',recentPermits:'أحدث التصاريح',permitKinds:'التصاريح حسب النوع',liveData:'بيانات مباشرة',viewAll:'عرض الكل',formCount:'النماذج المرجعية',submittedForms:'النماذج المرسلة',archivedForms:'النماذج المؤرشفة',duplicateForm:'رقم النموذج مستخدم مسبقًا.'});
async function dashboard(){const [p,a,c,f,forms,people,activities]=await Promise.all([all('ptw'),all('audits'),all('certificates'),all('findings'),all('formRecords'),all('personnel'),all('trail')]);const live=x=>x.filter(r=>!r.deletedAt),activePTW=live(p).filter(x=>!['Closed','Archived'].includes(x.status)),pendingPTW=live(p).filter(x=>['Submitted','Under Review'].includes(x.status)),openFindings=live(f).filter(x=>!['Closed','Archived'].includes(x.status)),highFindings=openFindings.filter(x=>x.risk==='High'),recent=live(p).sort((x,y)=>(y.updatedAt||y.createdAt||'').localeCompare(x.updatedAt||x.createdAt||'')).slice(0,5),latest=activities.sort((x,y)=>y.time.localeCompare(x.time)).slice(0,4),hot=activePTW.filter(x=>x.kind==='Hot').length,cold=activePTW.filter(x=>x.kind==='Cold').length,maxBar=Math.max(hot,cold,1);const certStatus=x=>x.status||((x.expiry||'')<day()?'Expired':(Date.parse(x.expiry)-Date.now())/86400000<30?'Expiring Soon':'Valid');let compliance=live(a).filter(x=>Number.isFinite(+x.compliance)).map(x=>+x.compliance);const cards=[metric(t('openPTW'),activePTW.length,`${t('totalPTW')}: ${live(p).length}`,'▤','green'),metric(t('pendingApproval'),pendingPTW.length,t('workflow'),'◷','amber'),metric(t('openFindings'),openFindings.length,`${t('highRisk')}: ${highFindings.length}`,'⚑','rose'),metric(t('totalPersonnel'),live(people).length,t('records'),'♙','blue')];return `${pageHead('welcome',t('welcomeSub'),role&&allowed('create','ptw')?`<a class="btn primary dashboard-action" href="/ptw/ptw-register.html">＋ ${t('add')}</a>`:'')}<div class="cards dashboard-cards">${cards.join('')}</div><div class="dashboard-grid"><section class="panel chart-panel"><div class="panelhead"><div><h2>${t('permitKinds')}</h2><span class="muted">${t('liveData')}</span></div><a class="btn small" href="/reports/reports.html">${t('reports')}</a></div><div class="permit-bars"><div class="bar-row"><div class="progress"><i style="height:${Math.round(hot/maxBar*100)}%"></i></div><b>${hot}</b><span>${t('hot')}</span></div><div class="bar-row bar-cold"><div class="progress"><i style="height:${Math.round(cold/maxBar*100)}%"></i></div><b>${cold}</b><span>${t('cold')}</span></div></div><div class="dashboard-mini-stats"><div><span>${t('validCert')}</span><b>${live(c).filter(x=>certStatus(x)==='Valid').length}</b></div><div><span>${t('activeAudits')}</span><b>${live(a).filter(x=>!['Closed','Archived'].includes(x.status)).length}</b></div><div><span>${t('compliance')}</span><b>${compliance.length?`${Math.round(compliance.reduce((x,y)=>x+y,0)/compliance.length)}%`:t('noDataShort')}</b></div><div><span>${t('formCount')}</span><b>${live(forms).length}</b></div></div></section><section class="panel activity-panel"><div class="panelhead"><h2>${t('recentActivity')}</h2><a class="link" href="/settings/audit-trail.html">${t('viewAll')}</a></div><div class="activity-feed">${latest.map(x=>`<div class="activity-item"><span class="activity-dot"></span><div><b>${esc(x.action)}</b><span>${esc(x.record||x.entity||'')}</span><small>${esc(roleName(x.user))} · ${new Date(x.time).toLocaleString(lang)}</small></div></div>`).join('')||`<div class="empty">${t('noData')}</div>`}</div></section></div><section class="panel recent-panel"><div class="panelhead"><div><h2>${t('recentPermits')}</h2><span class="muted">${t('openPTW')}</span></div><div class="toolbar"><a class="btn small" href="/ptw/ptw-register.html">${t('viewAll')}</a>${role&&allowed('create','ptw')?`<a class="btn primary small" href="/ptw/ptw-register.html">＋ ${t('add')}</a>`:''}</div></div><div class="tablewrap"><table><thead><tr>${['number','kind','area','company','date','status'].map(k=>`<th>${t(labels[k]||k)}</th>`).join('')}</tr></thead><tbody>${recent.map(r=>`<tr>${['number','kind','area','company','date','status'].map(k=>`<td>${colVal('ptw',r,k)}</td>`).join('')}</tr>`).join('')}</tbody></table>${recent.length?'':`<div class="empty">${t('noData')}</div>`}</div></section><section class="panel source-panel"><div class="panelhead"><h2>${t('sourceImages')}</h2><a class="link" href="/REFERENCE_FORM_ANALYSIS.md">${lang==='ar'?'عرض تحليل النماذج':'View form analysis'}</a></div><p class="muted">${t('sourceText')}</p><div class="toolbar">${Array.from({length:14},(_,i)=>`<a class="btn small" target="_blank" href="/assets/images/${i+1}.jpg">${i+1}.jpg</a>`).join('')}</div><p><a class="btn primary small" href="/forms/forms.html">${t('forms')}</a></p></section><section class="panel workflow-panel"><div class="panelhead"><h2>${t('workflow')}</h2></div><div class="workflow-steps">${['Draft','Submitted','Under Review','Approved','Rejected','Closed','Archived'].map(s=>`<span>${esc(trStatus(s))}</span>`).join('<i aria-hidden="true">→</i>')}</div></section>`}const labels={number:'number',kind:'kind',area:'area',company:'company',person:'person',date:'date',closedDate:'closedDate',requiredCert:'requiredCert',discipline:'discipline',description:'description',status:'status',attachments:'attachments',type:'certificateType',issue:'issue',expiry:'expiry',name:'name',contact:'contact',auditor:'auditor',category:'category',checklist:'checklist',compliance:'complianceLabel',risk:'risk',due:'due',recommendation:'recommendation'};
async function formField(entity,[key,type,required,options],record={}){const value=record[key]??'';let input='';if(type==='workflow'){const opts=entity==='ptw'?['Draft','Submitted','Under Review','Approved','Rejected','Closed']:['Draft','Submitted','Under Review','Closed'];input=`<select name="${key}">${opts.map(s=>`<option value="${s}" ${value===s?'selected':''}>${trStatus(s)}</option>`).join('')}</select>`}else if(type==='certstatus'){const opts=['Pending Verification','Valid','Expiring Soon','Expired','Suspended'];input=`<select name="${key}">${opts.map(s=>`<option value="${s}" ${value===s?'selected':''}>${trStatus(s)}</option>`).join('')}</select>`}else if(type==='cert-link'){const certs=(await all('certificates')).filter(c=>!c.deletedAt&&c.expiry>=day()&&!['Suspended','Expired'].includes(c.status)&&(record.person?c.person===record.person:true));input=`<select name="${key}" id="required-cert"><option value="">${t('select')}</option>${certs.map(c=>`<option value="${esc(c.id)}" data-type="${esc(c.type)}" ${record.certificateIds?.includes(c.id)?'selected':''}>${esc(c.type)} — ${esc(c.person)} (${esc(c.number)})</option>`).join('')}</select><small class="muted">${lang==='ar'?'اختر الموظف أولاً لعرض شهاداته السارية فقط.':'Select personnel first to show only their valid certificates.'}</small>`}else if(type==='select')input=`<select name="${key}"><option value="">${t('select')}</option>${options.map(x=>`<option value="${x}" ${x===value?'selected':''}>${x==='Hot'?t('hot'):x==='Cold'?t('cold'):x==='High'?t('riskHigh'):x==='Medium'?t('riskMedium'):x==='Low'?t('riskLow'):x}</option>`).join('')}</select>`;else if(type==='company'||type==='person'){const table=type==='company'?'companies':'personnel',items=(await all(table)).filter(r=>!r.deletedAt);input=`<select name="${key}"><option value="">${t('select')}</option>${items.map(x=>`<option value="${esc(x.name)}" ${value===x.name?'selected':''}>${esc(x.name)}</option>`).join('')}</select>`}else if(type==='textarea')input=`<textarea name="${key}">${esc(value)}</textarea>`;else if(type==='file')input=`<input name="${key}" type="file" multiple accept=".pdf,.jpg,.jpeg,.png,.docx,.xlsx">${value?`<small>${esc(value)}</small>`:''}`;else input=`<input class="field" name="${key}" type="${type}" value="${esc(value)}" ${type==='number'?'min="0" max="100"':''}>`;return `<div class="formrow ${type==='textarea'?'full':''}"><label>${t(labels[key]||key)} ${required?'*':''}</label>${input}</div>`}
async function openForm(entity,record={}){if(!allowed(record.id?'edit':'create',entity)){toast(t('forbidden'));return}const spec=specs[entity],modal=document.createElement('div');modal.className='modalback';modal.innerHTML=`<div class="modal"><div class="modalhead"><h2>${t(record.id?'edit':'add')} • ${t(spec.title)}</h2><button class="btn small" data-close>×</button></div><form id="recordform"><div class="formgrid">${(await Promise.all(spec.fields.map(f=>formField(entity,f,record)))).join('')}</div><p class="muted">${t('owner')}: ${roleName(spec.owner)}</p><div class="toolbar"><button class="btn primary" type="submit">${t('save')}</button><button class="btn" type="button" data-close>${t('cancel')}</button></div></form></div>`;document.body.append(modal);modal.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>modal.remove());if(entity==='ptw'){const p=modal.querySelector('[name="person"]'),c=modal.querySelector('#required-cert');p?.addEventListener('change',async()=>{const certs=(await all('certificates')).filter(x=>!x.deletedAt&&x.person===p.value&&x.expiry>=day()&&!['Suspended','Expired'].includes(x.status));c.innerHTML=`<option value="">${t('select')}</option>`+certs.map(x=>`<option value="${esc(x.id)}" data-type="${esc(x.type)}">${esc(x.type)} — ${esc(x.person)} (${esc(x.number)})</option>`).join('')})}modal.querySelector('form').onsubmit=async e=>{e.preventDefault();const fd=new FormData(e.target),next={...record,id:record.id||uid(),createdAt:record.createdAt||new Date().toISOString(),updatedAt:new Date().toISOString()};for(const [k,v]of fd.entries()){if(v instanceof File){if(v.size){const id=uid();await put('attachments',{id,name:v.name,type:v.type,size:v.size,uploadedAt:new Date().toISOString(),uploadedBy:role,linkedEntity:entity,linkedId:next.id,blob:v});next.attachments=v.name}}else next[k]=v}if(spec.fields.some(f=>f[2]&&!next[f[0]])){toast(t('required'));return}
if(entity==='certificates'&&next.expiry<day()&&next.status!=='Expired'){toast(lang==='ar'?'الشهادة منتهية ولا يمكن استخدامها لهذا التصريح.':'This certificate has expired and cannot be used for this permit.');return}
if(['ptw','audits','findings'].includes(entity)){const before=record.status||'Draft',after=next.status||'Draft';if(!canTransition(before,after)){toast(t('noPermission'));return}}
if(entity==='ptw'&&next.requiredCert){const cert=(await all('certificates')).find(c=>c.id===next.requiredCert&&!c.deletedAt&&c.person===next.person&&c.expiry>=day()&&!['Suspended','Expired'].includes(c.status));if(!cert){toast(lang==='ar'?'الشهادة منتهية ولا يمكن استخدامها لهذا التصريح.':'This certificate has expired and cannot be used for this permit.');return}next.certificateIds=[cert.id];next.requiredCert=cert.type}
const old=record.id?JSON.stringify(record):'';if(entity==='audits'&&next.checklist){try{const rows=JSON.parse(next.checklist);const scored=rows.filter(x=>x.answer!=='NA');next.compliance=scored.length?Math.round(rows.filter(x=>x.answer==='Y').length/scored.length*100):''}catch{}}await put(entity,next);await log(record.id?'Updated':'Created',entity,next.number||next.name||next.id,old,JSON.stringify(next));modal.remove();toast(t('saved'));render()}}
function colVal(entity,r,key){if(key==='status'){let s=r.status||'Draft';if(entity==='certificates'&&!r.status)s=!r.expiry?'Pending Verification':r.expiry<day()?'Expired':(Date.parse(r.expiry)-Date.now())/86400000<=30?'Expiring Soon':'Valid';return `<span class="badge ${s.replaceAll(' ','')}">${esc(trStatus(s))}</span>`}if(key==='actions')return `<div class="actions"><button class="btn small" data-view="${r.id}">${t('view')}</button>${allowed('edit',entity)?`<button class="btn small" data-edit="${r.id}">${t('edit')}</button>`:''}${allowed('delete',entity)?`<button class="btn small danger" data-delete="${r.id}">${t('delete')}</button>`:''}</div>`;return esc(r[key]||'—')}
async function listPage(entity,filter=''){const spec=specs[entity],rows=(await all(entity)).filter(x=>filter?!!x.deletedAt:!x.deletedAt);const columns=entity==='ptw'?['number','kind','area','company','person','date','status']:entity==='audits'?['number','date','auditor','company','category','compliance','status']:entity==='certificates'?['number','type','person','company','issue','expiry','status']:entity==='personnel'?['number','name','company','discipline','contact']:entity==='companies'?['number','name','contact']:['number','description','risk','due','status'];return `${pageHead(spec.title,`${t('owner')}: ${roleName(spec.owner)}`,!filter&&allowed('create',entity)?`<button class="btn primary" id="create">＋ ${t('add')}</button>`:'')}<div class="panel"><div class="panelhead"><h2>${filter?t('archive'):t('all')}</h2><div class="toolbar"><input class="field" id="search" placeholder="${t('search')}"><button class="btn small" id="csv">${t('export')}</button></div></div><div class="tablewrap"><table><thead><tr>${columns.map(k=>`<th>${t(labels[k]||k)}</th>`).join('')}<th>${t('actions')}</th></tr></thead><tbody>${rows.map(r=>`<tr>${columns.map(k=>`<td>${colVal(entity,r,k)}</td>`).join('')}<td>${colVal(entity,r,'actions')}</td></tr>`).join('')}</tbody></table>${rows.length?'':`<div class="empty">${t('noData')}</div>`}</div></div>`}
function detail(entity,r){const body=Object.entries(r).filter(([k])=>!['id','deletedAt','createdAt','updatedAt'].includes(k)).map(([k,v])=>`<div class="formrow"><label>${t(labels[k]||k)}</label><div>${esc(v)}</div></div>`).join('');const modal=document.createElement('div');modal.className='modalback';modal.innerHTML=`<div class="modal"><div class="modalhead"><h2>${t('view')} • ${esc(r.number||r.name||'')}</h2><button class="btn small" data-close>×</button></div><div class="formgrid">${body}</div></div>`;document.body.append(modal);modal.querySelector('[data-close]').onclick=()=>modal.remove()}
async function bindList(entity,filter=''){const view=document.querySelector('#view');if(!filter&&allowed('create',entity))view.querySelector('#create').onclick=()=>openForm(entity);view.querySelector('#search').oninput=async e=>{const q=e.target.value.toLowerCase();view.querySelectorAll('tbody tr').forEach(tr=>tr.classList.toggle('hidden',!tr.innerText.toLowerCase().includes(q)))};view.querySelector('#csv').onclick=async()=>{const rs=(await all(entity)).filter(r=>filter?!!r.deletedAt:!r.deletedAt);const cols=Object.keys(specs[entity].fields.reduce((a,f)=>(a[f[0]]=1,a),{}));const csv=[cols.join(','),...rs.map(r=>cols.map(c=>'"'+String(r[c]||'').replaceAll('"','""')+'"').join(','))].join('\r\n');download(csv,`${entity}.csv`,'text/csv')};view.querySelectorAll('[data-view]').forEach(b=>b.onclick=async()=>detail(entity,(await all(entity)).find(r=>r.id===b.dataset.view)));view.querySelectorAll('[data-edit]').forEach(b=>b.onclick=async()=>openForm(entity,(await all(entity)).find(r=>r.id===b.dataset.edit)));view.querySelectorAll('[data-delete]').forEach(b=>b.onclick=async()=>{const id=b.dataset.delete;if(!confirm(t('confirmDelete')))return;const r=(await all(entity)).find(x=>x.id===id);r.deletedAt=new Date().toISOString();r.deletedBy=role;await put(entity,r);await log('Soft deleted',entity,r.number||r.name||id,'Active','Archived');toast(t('deleted'));render()})}
function download(s,name,type){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([s],{type}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),500)}
async function reports(){return `${pageHead('reports',t('reportBuilt'))}<div class="cards">${Object.keys(specs).map(k=>`<div class="panel"><h2>${t(specs[k].title)}</h2><p class="muted">${t('reportBuilt')}</p><button class="btn small" data-report="${k}">${t('export')}</button><button class="btn small" onclick="window.print()">${t('print')}</button></div>`).join('')}<div class="panel"><h2>${t('trailTitle')||'Audit Trail'}</h2><button class="btn small" id="trailcsv">${t('export')}</button></div></div>`}
function isFormOwner(tpl){if(role==='Administrator')return true;if(role==='Viewer / Read Only')return false;if(tpl.group==='PTW'||tpl.group==='Isolation')return ['Permit Controller','HSE / Safety Officer'].includes(role);return ['Certificate Officer','HSE / Safety Officer'].includes(role)}
function trTpl(tpl){return lang==='ar'?tpl.ar:tpl.name}function trField(f){return lang==='ar'?f[2]:f[1]}
